mapper.select:
SELECT COALESCE(MAX(sequence_no), 0) + 1
FROM dialogue_turns
WHERE session_id = #{sessionId, jdbcType=CHAR}

mapper.update:
UPDATE dialogue_turns
SET silence_ms = #{silenceMs}
WHERE turn_id = #{turnId, jdbcType=CHAR}
  AND silence_ms = 0
  AND interrupted = FALSE

UPDATE dialogue_turns
SET display_card = #{displayCard, jdbcType=LONGVARCHAR}
WHERE turn_id = #{turnId, jdbcType=CHAR}
  AND speaker = 'AI'
